"""Proposed Native bicycle/motorist source capture; only --check runs on CPU.

This runner requires an exclusively owned CARLA endpoint. It does not infer
intent, legal interference, accepted recording status, or video compatibility.
"""
from __future__ import annotations
import argparse
import hashlib
import json
import math
from pathlib import Path
import traceback

from cameras import camera_plan
from engineering import CANDIDATES,parameters
from geometry import check as geometry_check,open_drive

HERE=Path(__file__).resolve().parent
CASES=('witness_1','witness_2')
RATE_HZ=20
FRAMES=480

def check(case:str,candidate:str)->dict:
    if case not in CASES or candidate not in CANDIDATES:raise ValueError('Unknown exact bicycle case/candidate')
    geometry=geometry_check();plan=parameters(case,candidate);cameras=camera_plan(candidate)
    if len(cameras)!=4 or len({c['name'] for c in cameras})!=4:
        raise ValueError('Four distinct original views required')
    if [c['name'] for c in cameras]!=plan['knobs']['camera_profile']:
        raise ValueError('Camera and construction profile differ')
    if (plan['law_id'],plan['cell_id'])!=('NRS-484B-270-7a','C111294') or plan['intent_asserted']:
        raise ValueError('Frozen case or intent declaration differs')
    return {'passed':True,'case':case,'candidate':candidate,'geometry':geometry,
            'camera_names':[c['name'] for c in cameras],
            'native_imported':False,'physical_or_legal_outcome_claimed':False}

def footprint(actor):
    vertices=actor.bounding_box.get_world_vertices(actor.get_transform())
    points=sorted({(round(p.x,5),round(p.y,5)) for p in vertices})
    if len(points)!=4:raise RuntimeError('Original actor lacks four distinct ground corners')
    center=actor.get_transform().location
    angle=math.radians(actor.get_transform().rotation.yaw)
    front=(math.cos(angle),math.sin(angle));right=(-front[1],front[0])
    return [list(p) for p in sorted(points,key=lambda p:math.atan2(
        (p[1]-center.y)*front[0]-(p[0]-center.x)*front[1],
        (p[0]-center.x)*front[0]+(p[1]-center.y)*front[1]))]

def sample(actor,mapping,actor_class):
    transform=actor.get_transform();velocity=actor.get_velocity()
    waypoint=mapping.get_waypoint(transform.location,project_to_road=False)
    if waypoint is None:raise RuntimeError('Original actor lost Native lane projection')
    return {'actor_id':actor.id,'blueprint_id':actor.type_id,'declared_class':actor_class,
            'native_road_id':waypoint.road_id,'native_lane_id':waypoint.lane_id,
            'center_xy_m':[transform.location.x,transform.location.y],
            'heading_deg':transform.rotation.yaw,'body_xy_m':footprint(actor),
            'speed_mps':math.hypot(velocity.x,velocity.y),
            'control_brake':float(actor.get_control().brake)}

def execute(case: str, candidate: str, output: Path, host: str, port: int) -> dict:
    """Run the source-bound Native/Core/camera acquisition on an owned endpoint."""
    from runner_capture import execute as capture_execute
    check(case,candidate)
    config_path=Path(__file__).resolve().with_name('config.json')
    if not config_path.is_file():
        raise ValueError('Exact materialized config.json required')
    config=json.loads(config_path.read_text())
    if config.get('case_suffix')!=case or config.get('candidate_id')!=candidate:
        raise ValueError('Exact case/candidate configuration differs')
    return capture_execute(config,output,host,port)

if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('--case',choices=CASES)
    parser.add_argument('--candidate',choices=CANDIDATES)
    parser.add_argument('--check',action='store_true');parser.add_argument('--execute',action='store_true')
    parser.add_argument('--output',type=Path);parser.add_argument('--output-dir',type=Path)
    parser.add_argument('--host');parser.add_argument('--port',type=int)
    args=parser.parse_args()
    config_path=Path(__file__).resolve().with_name('config.json')
    config=json.loads(config_path.read_text()) if config_path.is_file() else {}
    case=args.case or config.get('case_suffix')
    candidate=args.candidate or config.get('candidate_id')
    if args.output_dir is not None:args.execute=True
    if args.check==args.execute:raise SystemExit('Choose exactly one of --check or --execute')
    if args.check:print(json.dumps(check(case,candidate),sort_keys=True))
    else:
        destination=args.output_dir or args.output
        if destination is None or args.host is None or args.port is None:
            raise SystemExit('Native execution requires output directory, host and port')
        print(json.dumps(execute(case,candidate,destination,args.host,args.port)))

"""Unselected bicycle and motorist interaction candidates with source-bound triggers."""
from __future__ import annotations
import hashlib
import json
from pathlib import Path

CASES=('witness_1','witness_2')
CANDIDATES=('primary','fallback1','fallback2','fallback3')
BASE={'bicycle_route_tracking_lookahead_m':5.0,
      'motorist_clearance_buffer_s':1.0,'overview_fov_deg':90.0,
      'rate_hz':20,'duration_s':24.0,
      'camera_profile':['overview','bicycle_approach','motorist_approach','conflict']}
CHANGES={'primary':{},'fallback1':{'bicycle_route_tracking_lookahead_m':3.0},
         'fallback2':{'motorist_clearance_buffer_s':2.0},
         'fallback3':{'overview_fov_deg':105.0}}
TRIGGERS={
 'fallback1':{'metric':'max_bicycle_route_cross_track_error_m','op':'>','threshold':0.45,
              'source':'original Native bicycle pose joined to authored route and map readback'},
 'fallback2':{'metric':'min_motorist_conflict_clearance_s','op':'<','threshold':1.0,
              'source':'original Native motor-vehicle pose and full body joined to bicycle full body'},
 'fallback3':{'metric':'min_projected_body_frame_margin_px','op':'<','threshold':40,
              'source':'original Native bicycle/motor-vehicle full-body vertices, original overview camera pose/calibration, and decoded overview frame count'}}

def parameters(case:str,candidate:str)->dict:
 if case not in CASES or candidate not in CANDIDATES:raise ValueError('Unknown case or candidate')
 return {'case':case,'candidate':candidate,'knobs':BASE|CHANGES[candidate],
         'fallback_trigger':TRIGGERS.get(candidate),
         'source_status':'planned_original_native_or_video_not_observed',
         'law_id':'NRS-484B-270-7a','cell_id':'C111294',
         'comparison_variable':'bicycle_path_intervention',
         'rider_command':'hold_before_motorist_crosses' if case=='witness_1' else 'enter_before_motorist_crosses',
         'intent_asserted':False,
         'intent_physically_verified':False,'legal_interference_verdict':None}

def evaluate_trigger(candidate:str,metrics:dict,source:Path,expected_sha256:str,
                     diagnostic:bool=False)->bool:
 if candidate not in TRIGGERS:raise ValueError('Only fallbacks have triggers')
 raw=source.read_bytes()
 if hashlib.sha256(raw).hexdigest()!=expected_sha256:raise ValueError('Original source hash differs')
 record=json.loads(raw)
 permitted=('original_native_and_video','synthetic_original_shape_emulation') if diagnostic else ('original_native_and_video',)
 if record!=metrics or record.get('source_kind') not in permitted:
  raise ValueError('Metrics are not bound to original Native and video')
 trigger=TRIGGERS[candidate];value=record.get(trigger['metric'])
 if type(value) not in (int,float):raise ValueError('Missing measured fallback metric')
 return value>trigger['threshold'] if trigger['op']=='>' else value<trigger['threshold']

"""Source-bound bicycle/motorist effect diagnostic; intent remains unproven."""
from __future__ import annotations
import hashlib
import json
import math
from pathlib import Path

FRAMES=480
RATE_HZ=20
CASES=('witness_1','witness_2')
INTERSECTION=(-7.,-7.,7.,7.)

def sha(path:Path)->str:return hashlib.sha256(path.read_bytes()).hexdigest()
def bicycle_y(case:str,frame:int)->float:
    return (-25+.13*frame if frame<100 else -12. if frame<190 else -12+.13*(frame-190)) if case=='witness_1' else -25+.13*frame
def motor_x(case:str,frame:int)->float:
    return -25+.2*frame if case=='witness_1' else -25+.2*frame if frame<75 else -10. if frame<250 else -10+.2*(frame-250)
def bicycle_body(x:float,y:float)->list[list[float]]:
    return [[x-.35,y-.9],[x+.35,y-.9],[x+.35,y+.9],[x-.35,y+.9]]
def motor_body(x:float,y:float)->list[list[float]]:
    return [[x-2.5,y-1.1],[x+2.5,y-1.1],[x+2.5,y+1.1],[x-2.5,y+1.1]]
def bounds(body:list[list[float]])->tuple[float,float,float,float]:
    return min(p[0] for p in body),min(p[1] for p in body),max(p[0] for p in body),max(p[1] for p in body)
def overlaps(a:tuple[float,float,float,float],b:tuple[float,float,float,float])->bool:
    return a[0]<b[2] and a[2]>b[0] and a[1]<b[3] and a[3]>b[1]
def clearance(a:tuple[float,float,float,float],b:tuple[float,float,float,float])->float:
    dx=max(0.,a[0]-b[2],b[0]-a[2]);dy=max(0.,a[1]-b[3],b[1]-a[3])
    return math.hypot(dx,dy)

def synthetic(case:str,map_sha256:str)->dict:
    if case not in CASES or len(map_sha256)!=64:raise ValueError('Unknown case or map hash')
    rows=[]
    for frame in range(FRAMES):
        by=bicycle_y(case,frame);mx=motor_x(case,frame)
        rows.append({'frame':frame,'video_frame':frame,'native_frame':frame,'time_s':frame/RATE_HZ,
            'bicycle':{'actor_id':101,'class':'human_powered_bicycle','center_xy_m':[1.75,by],
                       'body_xy_m':bicycle_body(1.75,by),'speed_mps':0. if case=='witness_1' and 100<=frame<190 else 2.6},
            'motor_vehicle':{'actor_id':202,'class':'motor_vehicle','center_xy_m':[mx,-1.75],
                             'body_xy_m':motor_body(mx,-1.75),'speed_mps':0. if case=='witness_2' and 75<=frame<250 else 4.,
                             'brake_applied':case=='witness_2' and 75<=frame<250}})
    return {'format':'c111294-cycle-motor-source-v1','source_kind':'synthetic_cpu',
            'law_id':'NRS-484B-270-7a','cell_id':'C111294','actor':'cycle_or_scooter_operator',
            'case':case,'map_sha256':map_sha256,'rider_command_declared':
                'hold_before_motorist_crosses' if case=='witness_1' else 'enter_before_motorist_crosses',
            'intent_physically_verified':False,'legal_interference_claimed':False,'frames':rows}

def measure(source:Path,expected_sha256:str,road:Path)->dict:
    if not source.is_file():raise ValueError('Missing required source: interaction.json')
    if sha(source)!=expected_sha256:raise ValueError('Original interaction source missing or changed')
    data=json.loads(source.read_text())
    if data.get('format')!='c111294-cycle-motor-source-v1' or data.get('source_kind') not in (
            'synthetic_cpu','synthetic_original_shape_emulation','original_native_and_video'):
        raise ValueError('Wrong bicycle/motorist source format')
    if (data.get('law_id'),data.get('cell_id'),data.get('actor'))!=('NRS-484B-270-7a','C111294','cycle_or_scooter_operator'):
        raise ValueError('Frozen law/cell/actor source differs')
    if not road.is_file() or data.get('map_sha256')!=sha(road):raise ValueError('Authored road source differs')
    case=data.get('case')
    if case not in CASES or data.get('intent_physically_verified') is not False or data.get('legal_interference_claimed') is not False:
        raise ValueError('Case or intent claim differs')
    command='hold_before_motorist_crosses' if case=='witness_1' else 'enter_before_motorist_crosses'
    if data.get('rider_command_declared')!=command:raise ValueError('Rider command source differs')
    rows=data.get('frames')
    if not isinstance(rows,list) or len(rows)!=FRAMES:raise ValueError('Full 480-frame interaction source required')
    bike_cross=[];motor_cross=[];brake=[];minimum=math.inf
    prior=None;previous_native_frame=None
    original=data['source_kind'] in ('synthetic_original_shape_emulation','original_native_and_video')
    for index,row in enumerate(rows):
        native_frame=row.get('native_frame')
        native_ok=(type(native_frame) is int and native_frame>=0 and
                   (previous_native_frame is None or native_frame>previous_native_frame)) if original else native_frame==index
        if (row.get('frame'),row.get('video_frame'))!=(index,index) or not native_ok or abs(row.get('time_s',-1)-index/RATE_HZ)>1e-8:
            raise ValueError('Original frame/time join differs')
        previous_native_frame=native_frame
        bike=row.get('bicycle');motor=row.get('motor_vehicle')
        if not isinstance(bike,dict) or not isinstance(motor,dict) or bike.get('actor_id')==motor.get('actor_id'):
            raise ValueError('Separate source actors required')
        if bike.get('class')!=('bicycle_blueprint_unverified_propulsion' if original else 'human_powered_bicycle') or motor.get('class')!='motor_vehicle':
            raise ValueError('Bicycle/motorist class source differs')
        if original and (bike.get('blueprint_id')!='vehicle.bh.crossbike' or
                         not str(motor.get('blueprint_id','')).startswith('vehicle.')):
            raise ValueError('Original bicycle/motorist blueprint source differs')
        for actor,name,half in ((bike,'bicycle',bicycle_body),(motor,'motor',motor_body)):
            center=actor.get('center_xy_m');body=actor.get('body_xy_m');speed=actor.get('speed_mps')
            if not isinstance(center,list) or len(center)!=2 or not isinstance(body,list) or len(body)!=4 or type(speed) not in (int,float) or speed<0:
                raise ValueError('Original body/pose/speed absent: '+name)
            if any(type(v) not in (int,float) or not math.isfinite(v) for v in center):raise ValueError('Original center invalid')
            if original:
                if any(not isinstance(p,list) or len(p)!=2 or any(type(v) not in (int,float) or not math.isfinite(v) for v in p) for p in body):
                    raise ValueError('Original body/pose differs: '+name)
                if len({tuple(round(v,4) for v in p) for p in body})!=4:
                    raise ValueError('Original body corners differ: '+name)
                box=bounds(body)
                if not (box[0]<=center[0]<=box[2] and box[1]<=center[1]<=box[3] and box[2]-box[0]>.1 and box[3]-box[1]>.1):
                    raise ValueError('Original body/pose differs: '+name)
            elif {tuple(round(v,4) for v in p) for p in body}!={tuple(round(v,4) for v in p) for p in half(*center)}:
                raise ValueError('Original body/pose differs: '+name)
        if prior and (math.dist(bike['center_xy_m'],prior[0])>.21 or math.dist(motor['center_xy_m'],prior[1])>.21):
            raise ValueError('Original actor path discontinuity')
        prior=(bike['center_xy_m'],motor['center_xy_m'])
        bb=bounds(bike['body_xy_m']);mb=bounds(motor['body_xy_m'])
        if overlaps(bb,INTERSECTION):bike_cross.append(index)
        if overlaps(mb,INTERSECTION):motor_cross.append(index)
        if motor.get('brake_applied') is True:brake.append(index)
        if overlaps(bb,INTERSECTION) or overlaps(mb,INTERSECTION):minimum=min(minimum,clearance(bb,mb))
    if not bike_cross or not motor_cross or not math.isfinite(minimum):raise ValueError('Interaction traversal source absent')
    if minimum<=0:raise ValueError('Actor bodies collide in source')
    if (case=='witness_1' and brake) or (case=='witness_2' and not brake):raise ValueError('Motorist response source differs')
    return {'format':'c111294-interaction-measurement-v1','case':case,
            'source_sha256':expected_sha256,'road_sha256':sha(road),'frames':FRAMES,
            'bicycle_intersection_first_frame':bike_cross[0],'motor_intersection_first_frame':motor_cross[0],
            'motor_braking_frames':len(brake),'minimum_actor_body_clearance_m':round(minimum,5),
            'motorist_braked':bool(brake),'bicycle_class_source_checked':True,
            'human_propulsion_physically_verified':False,
            'separate_motor_vehicle_source_checked':True,'rider_command_declared':command,
            'intent_physically_verified':False,'legal_interference_claimed':False,
            'physical_behavior_observed':data['source_kind']=='original_native_and_video'}

if __name__=='__main__':
    import argparse
    p=argparse.ArgumentParser();p.add_argument('--source',type=Path,required=True)
    p.add_argument('--sha256',required=True);p.add_argument('--road',type=Path,required=True)
    a=p.parse_args();print(json.dumps(measure(a.source,a.sha256,a.road),sort_keys=True))

"""Source-hashed measurements for three C111294 fallback decisions.

Pixel margin is a projection of original body vertices through the surveyed
camera, with video decode proving frame count. It does not claim visibility.
"""
from __future__ import annotations
import argparse
import hashlib
import json
import math
from pathlib import Path
import subprocess

COUNT=480
SOURCES=('road.xodr','interaction.json','native_samples.jsonl',
         'video_frames.jsonl','camera_context.json','overview.mkv')


def sha(path:Path)->str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def rows(path:Path)->list[dict]:
    return [json.loads(line) for line in path.read_text().splitlines() if line.strip()]


def bounds(body:list[list[float]])->tuple[float,float,float,float]:
    return (min(p[0] for p in body),min(p[1] for p in body),
            max(p[0] for p in body),max(p[1] for p in body))


def clearance(a:tuple,b:tuple)->float:
    dx=max(0.,a[0]-b[2],b[0]-a[2]);dy=max(0.,a[1]-b[3],b[1]-a[3])
    return math.hypot(dx,dy)


def projected_margin(point:list[float],camera:dict)->float:
    pose=camera['pose'];x,y,z=pose['xyz_m'];yaw=math.radians(pose['yaw_deg']);pitch=math.radians(pose['pitch_deg'])
    dx,dy,dz=point[0]-x,point[1]-y,point[2]-z
    forward=dx*math.cos(pitch)*math.cos(yaw)+dy*math.cos(pitch)*math.sin(yaw)+dz*math.sin(pitch)
    width,height=camera['width'],camera['height']
    if forward<=.01:return -float(max(width,height))
    right=-dx*math.sin(yaw)+dy*math.cos(yaw)
    up=-dx*math.sin(pitch)*math.cos(yaw)-dy*math.sin(pitch)*math.sin(yaw)+dz*math.cos(pitch)
    focal=width/(2*math.tan(math.radians(camera['fov_deg'])/2))
    u=width/2+focal*right/forward;v=height/2-focal*up/forward
    return min(u,width-u,v,height-v)


def video_shape(path:Path)->tuple[int,int,int]:
    result=subprocess.run(['ffprobe','-v','error','-count_frames','-select_streams','v:0',
        '-show_entries','stream=width,height,nb_read_frames','-of','json',str(path)],
        text=True,capture_output=True,timeout=120)
    if result.returncode:raise ValueError('Original overview decode failed')
    stream=json.loads(result.stdout)['streams'][0]
    return int(stream['width']),int(stream['height']),int(stream['nb_read_frames'])


def measure(attempt:Path)->dict:
    attempt=attempt.resolve()
    manifest_path=attempt/'capture/manifest.json'
    if not manifest_path.is_file():raise ValueError('Missing original capture manifest')
    manifest=json.loads(manifest_path.read_text())
    declared=manifest.get('sources',{})
    for name in SOURCES:
        path=attempt/name
        if not path.is_file():raise ValueError('Missing trigger source: '+name)
        if declared.get(name)!=sha(path):raise ValueError('Trigger source hash absent or changed: '+name)
    interaction=json.loads((attempt/'interaction.json').read_text())
    source_kind=interaction.get('source_kind')
    if source_kind not in ('synthetic_original_shape_emulation','original_native_and_video'):
        raise ValueError('Original-shaped interaction source required')
    from measure import measure as measure_interaction
    measure_interaction(attempt/'interaction.json',declared['interaction.json'],attempt/'road.xodr')
    native=rows(attempt/'native_samples.jsonl');mapping=rows(attempt/'video_frames.jsonl')
    if len(native)!=COUNT or len(mapping)!=COUNT or len(interaction.get('frames',[]))!=COUNT:
        raise ValueError('Full 480-frame trigger join required')
    camera=json.loads((attempt/'camera_context.json').read_text())
    if camera.get('name')!='overview' or any(type(camera.get(key)) not in (int,float) for key in ('width','height','fov_deg')):
        raise ValueError('Overview calibration absent')
    if video_shape(attempt/'overview.mkv')!=(camera['width'],camera['height'],COUNT):
        raise ValueError('Original overview dimensions or frames differ')
    errors=[];seconds=[];margins=[];prior=None
    for index,(sample,mapped,source) in enumerate(zip(native,mapping,interaction['frames'])):
        frame=mapped.get('native_frame')
        if (mapped.get('video_frame'),mapped.get('carla_frame'),sample.get('native_frame'),source.get('native_frame'))!=(index,frame,frame,frame):
            raise ValueError('Original trigger frame identity differs')
        if type(frame) is not int or (prior is not None and frame<=prior):
            raise ValueError('Original trigger frame order differs')
        prior=frame
        if sample.get('bicycle')!=source.get('bicycle') or sample.get('motor_vehicle')!=source.get('motor_vehicle'):
            raise ValueError('Original trigger actor source differs')
        bicycle=sample['bicycle'];motor=sample['motor_vehicle']
        if bicycle.get('blueprint_id')!='vehicle.bh.crossbike' or not motor.get('blueprint_id','').startswith('vehicle.'):
            raise ValueError('Original trigger actor class differs')
        bike_body=bicycle['body_xy_m'];motor_body=motor['body_xy_m']
        if any(len(body)!=4 for body in (bike_body,motor_body)):
            raise ValueError('Full actor bodies required')
        errors.append(abs(bicycle['center_xy_m'][0]-1.75))
        gap=clearance(bounds(bike_body),bounds(motor_body))
        seconds.append(gap/max(.1,bicycle['speed_mps']+motor['speed_mps']))
        for key,body in (('bicycle_body_vertices_m',bike_body),('motor_vehicle_body_vertices_m',motor_body)):
            vertices=sample.get(key)
            if not isinstance(vertices,list) or len(vertices)<8 or any(len(p)!=3 for p in vertices):
                raise ValueError('Original 3D actor vertices absent: '+key)
            observed={(round(p[0],4),round(p[1],4)) for p in vertices}
            expected={(round(p[0],4),round(p[1],4)) for p in body}
            if observed!=expected:raise ValueError('Original 2D/3D actor body differs: '+key)
            margins.extend(projected_margin(p,camera) for p in vertices)
    if not margins or not all(math.isfinite(value) for value in errors+seconds+margins):
        raise ValueError('Nonfinite fallback measurement')
    return {'format':'c111294-source-bound-fallback-metrics-v1','source_kind':source_kind,
        'max_bicycle_route_cross_track_error_m':round(max(errors),5),
        'min_motorist_conflict_clearance_s':round(min(seconds),5),
        'min_projected_body_frame_margin_px':round(min(margins),5),
        'sources':{name:declared[name] for name in SOURCES},
        'method':'original body/pose/control, camera readback and decoded video frame join',
        'limitations':['projection is not pixel visibility','braking and clearance do not establish rider intent or legal interference']}


if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('--attempt',type=Path,required=True)
    parser.add_argument('--output',type=Path,required=True);args=parser.parse_args()
    value=measure(args.attempt)
    with args.output.open('x') as stream:json.dump(value,stream,indent=2,allow_nan=False);stream.write('\n')
    print(json.dumps(value,sort_keys=True))
